INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷85·晋少帝本纪·开运三年十一月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/11bd80a1278ae2081bb275997aefcffa5b947ddc/content/books/zizhi-tongjian/vol-285/year-0946/part-05/sources/library/jiuwudaishi-085-946-november/source.txt", "note": "《旧五代史》卷85·晋少帝本纪·开运三年十一月，段落 jiu-wudaishi-205deb4a7860-p002046；已回查正文卷题及上下文，纸本及异文待核。", "id": "9acf8392-69f1-50b9-b6ac-3e5c7508d12d"}, {"title": "辽史·卷116·国语解·萧翰与后族姓名说法", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/11bd80a1278ae2081bb275997aefcffa5b947ddc/content/books/zizhi-tongjian/vol-285/year-0946/part-05/sources/library/liaoshi-116-xiao-kinship/source.txt", "note": "《辽史》卷116·国语解·萧翰与后族姓名说法，段落 liaoshi-7cd182a20e67-p005807；已回查正文卷题及上下文，纸本及异文待核。", "id": "df9ba9aa-ff1b-5b3e-b339-5387cd8fcc6e"}, {"title": "资治通鉴·卷285·开运三年·十一月至十二月及追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/11bd80a1278ae2081bb275997aefcffa5b947ddc/content/books/zizhi-tongjian/vol-285/year-0946/part-05/sources/library/tongjian-285-946-november-december/source.txt", "note": "《资治通鉴》卷285·开运三年·十一月至十二月及追述，段落 zizhi-tongjian-a63549944a71-p003389；已回查正文卷题及上下文，纸本及异文待核。", "id": "149d5af8-e38f-5998-bd0d-c6615aa24a62"}, {"title": "资治通鉴·卷285·开运三年·十月至十一月及追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/bf9e990066dba1dacd217dcd86a7c0d28b93b91c/content/books/zizhi-tongjian/vol-285/year-0946/part-04/sources/library/tongjian-285-946-october-november/source.txt", "note": "《资治通鉴》卷285·开运三年·十月至十一月及追述，段落 zizhi-tongjian-a63549944a71-p003388；已回查卷题、上下文与传主，纸本及异文待核。", "id": "07de3176-9c71-561c-a46f-742fe325de90"}, {"title": "新五代史·卷62·南唐世家·陈觉赴福州", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b581496bddc409a2722727b001b6e1fbe269b9b0/content/books/zizhi-tongjian/vol-285/year-0946/part-02/sources/library/xinwudaishi-062-chen-jue-fuzhou/source.txt", "note": "《新五代史》卷62·南唐世家·陈觉赴福州，段落 xin-wudaishi-b08f244b9241-p003142；已回查上下文与传主，底本原字保留，纸本及异文待核。", "id": "cef07fa0-ebe4-551b-8758-4a3b3e4794b6"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李守贞", "aliases": ["李守貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋内客省使。940年五月受命担任马全节讨伐李金全军队的都监，职务由《旧五代史》本纪补充。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "a3d16959-684f-5c82-b848-8dcbdc73e85a"}, {"name": "杜重威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朔州人，后晋将领，妻子是石敬瑭的妹妹乐平长公主。937年以护圣都指挥使身份率军驻卫州。", "biography": null, "status": "draft", "id": "e5e23c10-447f-5238-bc56-f376300f9bac"}, {"name": "高谟翰", "aliases": ["高謨翰", "高模翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：高谟翰，契丹前锋将领。", "biography": null, "status": "draft", "id": "70516658-fa9a-5bd1-8a0a-55b9844d4772"}, {"name": "梁汉璋", "aliases": ["梁漢璋"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "应州人，后晋陈州防御使。944年二月乙巳与李守贞、皇甫遇、薛怀让等率合计一万军队沿河水陆进兵。生卒年本批未核。", "biography": null, "status": "draft", "id": "f62e9bd0-d874-521f-b4ff-27f731b77abb"}, {"name": "李仁达", "aliases": ["李仁達", "李弘义", "李弘義", "李弘达", "李弘達", "李宏达", "李宏達", "李达", "李達"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "光州人，曾任闽元从指挥使，多次在建州、福州之间投奔不同执政者。945年与陈继珣、黄仁讽发动福州政变，杀王继昌和吴成义，拥立僧卓岩明。后来又杀黄仁讽、陈继珣，将福州兵权集中到自己手中。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "97ca7dea-54b1-5a38-a747-3dc803037d55"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "王建封", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "上元人，南唐将领。945年《资治通鉴》记他以先锋桥道使身份率先登上建州城墙，南唐军随后攻破建州。生卒年本段未载。", "biography": null, "status": "draft", "id": "a7b5c6e1-9057-52ff-8317-f82698daacd6"}, {"name": "王崇文", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐百胜军节度使。945年建州陷落后受任永安节度使，《资治通鉴》记他治理宽简，建州百姓渐安。生卒年本段未载。", "biography": null, "status": "draft", "id": "e00c8607-6426-5398-b911-e9eba22c7740"}, {"name": "陈觉", "aliases": ["陳覺"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：陈觉，海陵人、参与谈议者。", "biography": null, "status": "draft", "id": "8f8c34eb-c238-596f-a688-8b8332b405a1"}, {"name": "冯延鲁", "aliases": ["馮延魯"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冯延巳的弟弟，南唐官员，曾任东都判官、礼部员外郎，与兄长同在元帅府。曾请求允许百姓卖子女；李昪去世后又参与起草包含这一规定的遗诏。生卒年尚未核。", "biography": null, "status": "draft", "id": "a589c28e-c0c5-58bf-989f-96457604ccdd"}, {"name": "魏岑", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐齐王府僚属。李昪在位时，常梦锡曾反对他与陈觉、冯延巳等陪侍李璟。生卒年尚未核。", "biography": null, "status": "draft", "id": "58f25557-fd68-5851-90ad-b847734e7dfe"}, {"name": "留从效", "aliases": ["留從效", "留從効"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "泉州散员指挥使，主书称桃林人，《宋史》记泉州永春人。944年参与杀黄绍颇、迎王继勋，并任都指挥使。新史写留從効，沿用同一主体。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "55786b2f-a228-5281-a323-e9c521b2988f"}, {"name": "杜昌业", "aliases": ["杜昌業"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐江州观察使。943年冯延鲁升中书舍人、勤政殿学士后，他批评仅因言语合意便授高官会使日后功臣难以获得适当奖赏。生卒年尚未核。", "biography": null, "status": "draft", "id": "c4dbe076-e0c1-54df-a3e4-875c08c1fec6"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "张彦泽", "aliases": ["張彥澤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，938年任镇国军节度使，在华州截击并杀死东行的凤翔叛军。生卒年本段未载。", "biography": null, "status": "draft", "id": "194d0f9a-3b17-5635-9741-dffc983ee32e"}, {"name": "田行皋", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀施州刺史。946年十一月条下记他叛变，后蜀派供奉官耿彦珣率兵讨伐；原文未给平定结果及生卒年。", "biography": null, "status": "draft", "id": "3e9f4060-5494-5ef9-b6ac-3918c43ce4f8"}, {"name": "耿彦珣", "aliases": ["耿彥珣"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀供奉官。946年十一月条下记奉命领兵讨伐施州刺史田行皋。生卒年、籍贯及平叛结果未载；不同名的陈彦珣不据近名合并。", "biography": null, "status": "draft", "id": "9a179568-d7b9-501a-a9ce-ea979a2506a5"}, {"name": "李谷", "aliases": ["李穀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：李谷，汝阴进士、送别友人。", "biography": null, "status": "draft", "id": "33cb8b51-1e37-5d5f-ab22-b339b991020d"}, {"name": "萧翰", "aliases": ["蕭翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹将领。946年十一月条下记他与通事刘重进带兵绕到晋军后方，截断粮道及归路，进至栾城接受驻军投降。《资治通鉴》称他是契丹主耶律德光的舅舅，《辽史》保存了不同的亲属说法并质疑相关姓名起源说；具体亲属关系暂待核对。生卒年本批未核。", "biography": null, "status": "draft", "id": "defe15da-7bbc-56ed-9d88-0ec31a88fcaf"}, {"name": "刘重进（契丹通事）", "aliases": ["刘重进", "劉重進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹通事。946年十一月条下记与萧翰率百骑及其他士卒绕到晋军后方，断粮道及归路，进至栾城。与后汉、后周任节度使的同名刘重进是否同人尚未确认，暂分别识别；生卒年未载。", "biography": null, "status": "draft", "id": "cf2a1610-06dc-5169-8f6e-97abf121abca"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
